#!/bin/bash
# Kit fixes 2026-11-22 (lane/kit-fixes-20261122): re-installs of the large recipes whose installed GLB the kit fixes made
# stale (scripts/building-recipes/stale-installs.ts --ids after the lane: exactly these six). Allow strings are the ones each
# house was installed or staged with (kit-batch-2005 install.sh, kit-batch-8504 allow-of.sh, Wiborgeiland from its catalogue
# limitations). Not here: Gustav Mahlerlaan 7-27 (fails openings-within-walls), Zeeburgerdijk 275 kit2 (not installed),
# Leeuwendalersweg 400-732 (mesh unchanged after re-expressing walls[2]).
# Run from the repository root with MAP_RECALL_SOURCE_DATA holding the crops of these pands; then LODs, covers, check:covers.
set -euo pipefail

# Borneostraat 42-70 (row split: per-house bay windows from the house's own first bay)
node --import tsx scripts/building-recipes/install-large.ts --house=borneostraat-42-70-253816 --install '--allow-inferred=0:blind2 new preferred 2/2, Borneostraat front read by hand from w01-26 2025-09-26 - raised brick bays with paired slot windows alternating with French-window bays under a zinc mansard and residential doors - the judge picks the 2022 crop w01-26L which shows scaffolding and site hoarding so it has no evidence;1:blind2 new preferred 2/2, Madurastraat front read by hand from w02-179 2024-09-16 - the same raised-bay and French-bay rhythm in 14 houses - the crop is 35 degrees oblique with a plane tree in front so the judge'"'"'s columns and glazing bands are unreliable;2:blind2 new preferred 2/2, NW corner front read by hand from w04-296 2023-01-02 - two raised bays with slot pairs between three French bays over shop windows in a brick ground - a parked van covers the lower left third and the judge counts the slot pairs and pale dormer glass wrongly;3:blind2 new preferred 2/2, Sumatrastraat front read by hand from w03-258d25L 2023-01-02 (re-cropped since the 2021 crop shows the building site) - three raised bays between French bays and a zinc mansard - the judge counts each slot pair as one column and reads pale dormer glass as wall'

# Bos en Lommerplein 2 (row split: house 1 bay windows from its own first bay)
node --import tsx scripts/building-recipes/install-large.ts --house=bos-en-lommerplein-2-097332 --install '--allow-inferred=0:tower and first balcony bays w04-163 2024-09-18, sunlit, window cadence read by hand;1:balcony front w05-163 2024-09-18 sun glare and shop stickers (glazing), wall hue in warm morning light;2:middle stretch cut at 13.9 m by 3DBAG, same balcony storeys as walls[1] on w04-163;3:upper face 3DBAG sets back behind the balconies, inferred from walls[1];4:east front w01-73L 2024-11-21 behind autumn trees, cadence per storey read by hand'

# Jesse Owenshof 1 (INRIT / UITRIT garage doors on walls 0 and 1, palette.garage)
node --import tsx scripts/building-recipes/install-large.ts --house=jesse-owenshof-1-131508 --install '--allow-inferred=0:w07-114n 2024-10-23 straight-on, window and loggia positions measured per bay, judge blocked by sky wash and hedge;1:w06-114n 2024-10-23, mirror layout measured the same way;4:w02-24n 2024-10-23, tree over the left third, layout mirrored from the visible right half, photo wall #0c130d is the tree;5:w09-24n 2024-10-23 in shade (photo wall #575552), pale brick white-balanced on the white frames of w06/w07;6:w10-24n 2025-06-30, mirror of walls[5], judge reads the shaded brick as stone;8:w13-99n 2025-06-30 sunlit, the judge counts the 12 ribbon lights as columns, red wall dL -0.04;10:w12-309 2016-07-11, same red end mirrored, the elevation sample lands on the pale neighbouring panel'

# Laing's Nekstraat 1-17 (row split: per-house bay windows and residential ground from each house's own first bay)
node --import tsx scripts/building-recipes/install-large.ts --house=laing-s-nekstraat-1-17-241221 --install '--allow-inferred=0:blind2 new preferred 2/2, Retiefstraat front read by hand from w02-158L 2022-01-12: seven house units by downpipe joints, two-bay loggias on storeys 2-3 over paired storey-1 windows, storage louvres and doors on the ground, the judge has no evidence as the camera stood 7.5 m from a 54 m wall and a plane tree covers the left third;1:blind2 new preferred 2/2, Tugelaweg front read by hand from w01-338 2020-01-29: white-framed window groups per storey placed by bayWindows and two portals, the crop is 42 deg oblique so mask IoU and columns are unreliable;2:blind2 new preferred 2/2, Hertzogstraat front read by hand from w03-65L 2018-12-11: single windows over a residential ground and projecting brick-parapet balconies by house on storeys 1-3, the judge folds the irregular window spacing into 8 columns and bare tree branches cover the lower storeys;3:blind2 new preferred 2/2, south-west front main panel read by hand from w04-245 2019-12-19: two brick-parapet balcony stacks on storeys 1-3, the wall is in deep shade and the stacks cover the window columns so wall lightness and glazing bands fail;4:blind2 new preferred 2/2, south-west south end read by hand from w04-245 2019-12-19: one brick-parapet balcony stack on storeys 1-3, the shaded wall and the stack soffits read as glazing to the judge'

# Veemkade 366-556 (walls[2] colonnade: the passage door over the two 1.4 m garage bays)
node --import tsx scripts/building-recipes/install-large.ts --house=veemkade-366-556-145730 --install '--allow-inferred=0:blind2 new preferred 3/3, Veemkade N front read by hand from w04-16 2025-06-16 - 22 transom axes over four brick storeys on a two-storey grey stone colonnade with glazed shops and a glazed mezzanine - the automatic judge counts the stone piers and the deep colonnade shade as wall and the N front is in full shadow so its colour and ground glazing read off;1:blind2 new preferred 3/3, N wing W end read by hand from w02-286 2025-06-16 - four axes over three tall podium windows (the kit cannot give the podium fewer bays) - judge reads the podium French windows as one band;2:blind2 new preferred 3/3, W colonnade read by hand from w02-286 2025-06-16 - twelve stone piers before a glazed shop storey and glazed mezzanine with the car park entrance - the judge classes the pale stone piers as a painted wall and cannot see the colonnade;3:blind2 new preferred 3/3, S tower read by hand from w03-196 2025-06-16 - eight axes on storeys 2-5 and four centred axes on storeys 6-9 with the glazed stair slot over the DETROIT entrance - trees and a lamp post cover the crop edges and the judge cannot weigh the open-bay pattern;4:blind2 new preferred 3/3, S tower shoulders read by hand from w03-196 2025-06-16 - blank brick over a glazed shop ground - too narrow for the judge'"'"'s storey bands;5:blind2 new preferred 3/3, S podium west of the tower read by hand from w03-196 2025-06-16 - blank brick with the shop name left and glazed shops right - tree in front and the judge cannot weigh a part-glazed plinth;7:blind2 new preferred 3/3, upper setbacks over the W podium read by hand from w02-286 2025-06-16 - punched transom grid on the tower W face and the stepped wings seen obliquely over the podium - set back 8-20 m so the rectified crop does not show them straight'

# Wiborgeiland (pand 0363100012247551; row split: per-house bays in walls 0 and 4; walls 3 re-expressed, unchanged)
node --import tsx scripts/building-recipes/install-large.ts --house=wiborgeiland-247551 --install '--allow-inferred=0:row of gabled quay houses split at the 3DBAG gable joints, the whole-wall grid misreads the row (g0);1:row of gabled quay houses split at the 3DBAG gable joints, the whole-wall grid misreads the row (g1);2:row of gabled quay houses split at the 3DBAG gable joints, the whole-wall grid misreads the row (g2);3:row of gabled quay houses split at the 3DBAG gable joints, the whole-wall grid misreads the row (g3);4:row of gabled quay houses split at the 3DBAG gable joints, the whole-wall grid misreads the row (g4);5:row of gabled quay houses split at the 3DBAG gable joints, the whole-wall grid misreads the row (g5);7:row of gabled quay houses split at the 3DBAG gable joints, the whole-wall grid misreads the row (g7);8:row of gabled quay houses split at the 3DBAG gable joints, the whole-wall grid misreads the row (g8)'
